<script lang="ts">
 import {onMount} from 'svelte';
 import {beforeNavigate,goto,invalidateAll} from '$app/navigation';
 import {newBlock,emptyDocument,renderDocument,normalizeDocument,auditDocument,blockLabels,type MailDocument,type MailBlock,type BlockKind} from '$lib/newsletter';
 import MailNav from './MailNav.svelte';
 import MailDialog from './MailDialog.svelte';
 import MailRichText from './MailRichText.svelte';
 import MailAudience from './MailAudience.svelte';
 import {audienceFilter,savedAudience,type AudienceFilter} from '$lib/newsletter-audience';
 type StudioData={facility:string;campaign:Record<string,any>|null;defaults?:Record<string,any>|null;template?:MailDocument;assets:Record<string,any>[];lists:Record<string,any>[];deliveries:Record<string,any>[];summary?:Record<string,number>|null};
 let {data}:{data:StudioData}=$props();
 // svelte-ignore state_referenced_locally
 const initial=data.campaign;
 // svelte-ignore state_referenced_locally
 const defaults=data.defaults;
 // svelte-ignore state_referenced_locally
 const template=data.template;
 let id=$state<string|null>(initial?.id??null),revision=$state<number>(initial?.revision??0);
 let doc=$state<MailDocument>(initial?.document?.blocks?normalizeDocument(initial.document):template?normalizeDocument(template):emptyDocument());
 let name=$state(initial?.name??'名称未設定'),subject=$state(initial?.subject??''),preheader=$state(initial?.preheader??'');
 let fromName=$state(initial?.from_name??defaults?.from_name??'山人-yamado-'),fromEmail=$state(initial?.from_email??defaults?.from_email??''),replyTo=$state(initial?.reply_to??defaults?.reply_to??'info@yamado.co.jp');
 let tags=$state<string[]>(initial?.audience_tags??[]),selected=$state(''),tab=$state('design'),mobile=$state(false),palette=$state('content');
 let filter=$state<AudienceFilter>(audienceFilter(initial?.audience_filter));
 let saving=$state(false),message=$state(''),savedKey=$state(''),lastAuto=$state(''),ready=$state(false),savedTime=$state('');
 let history=$state<string[]>([]),future=$state<string[]>([]),dragId=$state(''),count=$state<number|null>(null),confirming=$state(false),confirmCount=$state(''),schedule=$state('');
 let aiPrompt=$state(''),aiTone=$state('丁寧で上品'),aiKind=$state('body'),aiResult=$state(''),aiBusy=$state(false);
 let disabled=$derived((data.campaign?.status??'draft')!=='draft');
 const payload=()=>({id,revision,name,subject,preheader,document:doc,from_name:fromName,from_email:fromEmail,reply_to:replyTo,audience_tags:tags,audience_filter:filter});
 const key=()=>JSON.stringify({name,subject,preheader,document:doc,fromName,fromEmail,replyTo,tags,filter});
 let dirty=$derived(ready&&key()!==savedKey);
 let block=$derived(doc.blocks.find(b=>b.id===selected));
 let issues=$derived(auditDocument(doc));
 $effect(()=>{JSON.stringify(filter);tags.join('\n');count=null;});
 let preview=$derived(renderDocument(doc,preheader).replace('<head>','<head><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src https:; style-src \'unsafe-inline\';">'));
 onMount(()=>{savedKey=key();ready=true;const timer=setInterval(()=>{if(id&&!dirty&&!saving&&!aiBusy&&document.visibilityState==='visible')void invalidateAll().catch(()=>{});},10000);return()=>clearInterval(timer);});
 beforeNavigate(({cancel})=>{if(dirty&&!window.confirm('変更を保存していません。移動しますか？'))cancel();});
 $effect(()=>{const current=key();if(!ready||disabled||saving||current===savedKey||current===lastAuto)return;const timer=setTimeout(()=>{lastAuto=current;void save();},1800);return()=>clearTimeout(timer);});
 async function api(action:string,value:unknown){const form=new FormData();form.set('facility',data.facility);form.set('action',action);form.set('data',JSON.stringify(value));const res=await fetch('/admin/mail/api',{method:'POST',body:form});const result=await res.json();if(!res.ok)throw Error(result.error||'処理できませんでした。');return result.data;}
 async function save(){if(saving||disabled)return;saving=true;message='';const sentKey=key(),sent=payload();try{const r=await api('save',sent);id=r.id;revision=r.revision;savedKey=sentKey;savedTime=new Date().toLocaleTimeString('ja-JP');if(!sent.id)await goto('/admin/mail/'+r.id,{replaceState:true,keepFocus:true,noScroll:true});}catch(e){message=e instanceof Error?e.message:'保存に失敗しました。';}finally{saving=false;}}
 function checkpoint(){history=[...history.slice(-49),JSON.stringify(doc)];future=[];}
 function add(kind:BlockKind){checkpoint();const b=newBlock(kind);doc.blocks=[...doc.blocks,b];selected=b.id;}
 function undo(){if(!history.length)return;future=[...future,JSON.stringify(doc)];doc=JSON.parse(history.at(-1)!);history=history.slice(0,-1);}
 function redo(){if(!future.length)return;history=[...history,JSON.stringify(doc)];doc=JSON.parse(future.at(-1)!);future=future.slice(0,-1);}
 function move(bid:string,offset:number){const i=doc.blocks.findIndex(b=>b.id===bid),j=i+offset;if(j<0||j>=doc.blocks.length)return;checkpoint();const a=[...doc.blocks];[a[i],a[j]]=[a[j],a[i]];doc.blocks=a;}
 function drop(e:DragEvent,target:string){e.preventDefault();if(!dragId||dragId===target)return;checkpoint();const a=doc.blocks.filter(b=>b.id!==dragId),b=doc.blocks.find(b=>b.id===dragId);if(b){a.splice(a.findIndex(b=>b.id===target),0,b);doc.blocks=a;}dragId='';}
 async function saveAsset(kind:'template'|'block'){const label=window.prompt(kind==='template'?'テンプレート名':'保存ブロック名');if(!label)return;try{await api('asset',{kind,name:label,document:kind==='block'?{...doc,blocks:block?[block]:[]}:doc});message='保存しました。';await invalidateAll();}catch(e){message=String(e);}}
 function useAsset(document:MailDocument){checkpoint();doc=normalizeDocument({...document,blocks:document.blocks.map(b=>({...b,id:crypto.randomUUID()}))});}
 async function test(){if(dirty||!id){message='最新の内容を保存してからテスト送信してください。';return;}try{const r=await api('test',{id,revision});message=`テストメールを ${r.email} 宛に送信待ちへ登録しました。結果は配信状況に表示されます。`;await invalidateAll();}catch(e){message=String(e);}}
 async function audience(){const requested=JSON.stringify({tags,filter});try{const r=await api('count',{tags,filter});if(requested===JSON.stringify({tags,filter})){count=r.count;confirmCount='';}}catch(e){message=String(e);}}
 async function dispatch(){try{const at=schedule?new Date(schedule).toISOString():new Date().toISOString();await api('schedule',{id,revision,scheduled_at:at,count});confirming=false;await invalidateAll();message='配信を予約しました。';}catch(e){message=String(e);}}
 async function cancel(){try{await api('cancel',{id,revision});await invalidateAll();}catch(e){message=String(e);}}
 function chooseImage(url:string,alt:string){checkpoint();const target=doc.blocks.find(b=>b.id===selected&&b.kind==='image');if(target){target.url=url;target.alt=alt;}else{const next=newBlock('image');next.url=url;next.alt=alt;doc.blocks=[...doc.blocks,next];selected=next.id;}}
 async function uploadImage(file:File,targetId:string){try{const form=new FormData();form.set('file',file);form.set('facilityId',data.facility);const r=await fetch('/admin/mail/images',{method:'POST',body:form}),j=await r.json();if(!r.ok)throw Error(j.error??'アップロードできませんでした。');const target=doc.blocks.find(b=>b.id===targetId&&b.kind==='image');if(target&&!disabled){checkpoint();target.url=j.url;}await invalidateAll();}catch(e){message=String(e);}}
 async function generate(){if(aiBusy)return;aiBusy=true;aiResult='';try{const f=new FormData();f.set('facility',data.facility);f.set('kind',aiKind);f.set('prompt',aiPrompt);f.set('tone',aiTone);const r=await fetch('/admin/mail/ai',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.message??j.error??'生成できませんでした。');if(j.url){chooseImage(j.url,aiPrompt.slice(0,200));await invalidateAll();message='AI画像を追加しました。内容と代替テキストを確認してください。';}else aiResult=j.text;}catch(e){message=String(e);}finally{aiBusy=false;}}
 function applyAi(text:string){checkpoint();if(aiKind==='subject')subject=text;else{const next=newBlock(aiKind==='cta'?'button':'text');next.text=text;doc.blocks=[...doc.blocks,next];selected=next.id;}aiResult='';}
</script>

<svelte:head><title>{name} ｜ メール編集</title></svelte:head>
<svelte:window onbeforeunload={(e)=>{if(dirty){e.preventDefault();e.returnValue='';}}} onkeydown={(e)=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();void save();}}}/>
<MailNav/>
<header class="studio-header"><div><a href="/admin/mail" class="text-sm text-stone-500">← メール一覧</a><input aria-label="メール名" bind:value={name} disabled={disabled} class="mt-2 block w-full bg-transparent text-xl font-semibold"/></div><div class="flex flex-wrap items-center gap-2"><span aria-live="polite" class="text-sm text-stone-500">{saving?'保存中…':dirty?'未保存':savedTime?'保存済み '+savedTime:id?'保存済み':'新規・未保存'}</span><button class="btn" onclick={()=>void save()} disabled={saving||disabled}>保存</button>{#if id&&!dirty}<a class="btn" data-sveltekit-reload href={'/admin/mail/'+id+'/export'}>HTMLを書き出す</a>{/if}<button class="btn primary" onclick={()=>tab='checklist'}>配信チェックへ</button></div></header>
{#if message}<p role="status" class="my-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm">{message}</p>{/if}
<div class="mb-4 flex gap-2"><button class:current={tab==='design'} class="btn" onclick={()=>tab='design'}>デザイン</button><button class:current={tab==='checklist'} class="btn" onclick={()=>tab='checklist'}>配信チェックリスト</button><button class:current={tab==='results'} class="btn" onclick={()=>tab='results'}>配信状況</button></div>
{#if tab==='design'}
 <section class="studio">
  <aside class="tools"><div class="mb-4 flex flex-wrap gap-2"><button class="btn" onclick={()=>palette='content'}>コンテンツ</button><button class="btn" onclick={()=>palette='blocks'}>保存ブロック</button><button class="btn" onclick={()=>palette='uploads'}>画像</button><button class="btn" onclick={()=>palette='ai'}>AI</button></div>
  {#if palette==='content'}<div class="grid grid-cols-2 gap-2">{#each Object.entries(blockLabels) as [kind,label]}<button class="tile" onclick={()=>add(kind as BlockKind)} disabled={disabled}>＋ {label}</button>{/each}</div><div class="my-5 space-y-3"><label>背景色<input type="color" bind:value={doc.background} disabled={disabled}/></label><label>ブランドカラー<input type="color" bind:value={doc.accent} disabled={disabled}/></label><button class="btn w-full" onclick={()=>void saveAsset('template')} disabled={disabled}>テンプレートとして保存</button></div>
  {:else if palette==='blocks'}{#each data.assets.filter(a=>a.kind==='block'||a.kind==='template') as asset}<button class="tile mb-2 w-full" disabled={disabled} onclick={()=>asset.kind==='block'?(checkpoint(),doc.blocks=[...doc.blocks,...asset.document.blocks.map((b:MailBlock)=>({...b,id:crypto.randomUUID()}))]):useAsset(asset.document)}>{asset.name}</button>{:else}<p class="text-sm text-stone-500">よく使うブロックを選んで保存できます。</p>{/each}
  {:else if palette==='uploads'}<p class="mb-3 text-sm text-stone-500">クリックすると、選択中の画像ブロックへ反映します。画像ブロックが未選択なら追加します。</p><button class="btn mb-4 w-full" disabled={disabled} onclick={()=>add('image')}>画像をアップロードするブロックを追加</button><div class="grid grid-cols-2 gap-2">{#each data.assets.filter(a=>a.kind==='image') as asset}<button class="tile p-2" disabled={disabled} onclick={()=>chooseImage(asset.document.url,asset.document.alt??'')}><img src={asset.document.url} alt={asset.document.alt??asset.name} class="mb-2 h-24 w-full object-cover" loading="lazy"/><span class="block truncate text-sm">{asset.name}</span></button>{:else}<p class="text-sm text-stone-500">アップロードした画像・AI画像がここに保存されます。</p>{/each}</div>
  {:else if palette==='ai'}<div class="space-y-4"><h2 class="font-semibold">AIアシスタント</h2><label>作成するもの<select bind:value={aiKind}><option value="body">本文</option><option value="subject">件名</option><option value="cta">ボタンの文言</option><option value="image">画像</option></select></label><label>内容・条件<textarea rows="6" maxlength="2048" bind:value={aiPrompt} placeholder="商品・対象者・価格・期限など、含めたい事実を入力"></textarea></label>{#if aiKind!=='image'}<label>トーン<select bind:value={aiTone}><option>丁寧で上品</option><option>親しみやすい</option><option>簡潔で落ち着いた</option></select></label>{/if}<button class="btn primary w-full" disabled={aiBusy||disabled||!aiPrompt.trim()} onclick={()=>void generate()}>{aiBusy?'生成中…':'案を生成する'}</button><p class="text-sm text-stone-500">組織全体で1日あたり文章100回・画像20回まで。提案の事実・表現を確認してから採用してください。</p>{#if aiResult}<textarea rows="10" bind:value={aiResult} aria-label="AIの提案"></textarea>{#if aiKind==='body'}<button class="btn" onclick={()=>applyAi(aiResult)}>本文ブロックとして追加</button>{:else}{#each aiResult.split('\n').map(s=>s.replace(/^\s*\d+[.)、．]\s*/,'').trim()).filter(Boolean) as suggestion}<button class="tile w-full" onclick={()=>applyAi(suggestion)}>{suggestion}</button>{/each}{/if}{/if}</div>{/if}
  {#if block}<hr class="my-5 border-stone-200"/><h2 class="mb-3 font-semibold">{blockLabels[block.kind]}の設定</h2><fieldset disabled={disabled} class="space-y-3" onfocusin={()=>checkpoint()}>
   {#if block.kind==='richtext'}{#key block.id}<MailRichText bind:value={block.text} {disabled}/>{/key}{/if}
   {#if ['heading','text','button','html'].includes(block.kind)}<label>{block.kind==='html'?'HTMLコード':'テキスト'}<textarea rows={block.kind==='html'?12:6} bind:value={block.text}></textarea></label>{/if}
   {#if ['image','button'].includes(block.kind)}<label>{block.kind==='image'?'画像URL（HTTPS）':'リンク先URL'}<input bind:value={block.url}/></label>{/if}
   {#if block.kind==='image'}<label>代替テキスト<input bind:value={block.alt}/></label><label>画像を追加<input type="file" accept="image/png,image/jpeg,image/webp,image/avif" onchange={e=>{const f=e.currentTarget.files?.[0];if(f&&block)void uploadImage(f,block.id);}}/></label>{/if}
   <label>文字サイズ<input type="number" min="14" max="48" bind:value={block.size}/></label><label>余白<input type="number" min="0" max="64" bind:value={block.padding}/></label><label>配置<select bind:value={block.align}><option value="left">左</option><option value="center">中央</option><option value="right">右</option></select></label><label>文字色<input type="color" bind:value={block.color}/></label><label>背景色<input type="color" bind:value={block.background}/></label>
   <label>背景画像URL（HTTPS）<input bind:value={block.backgroundImage}/></label><p class="text-sm text-stone-500">画像非表示の受信環境に備え、背景色と文字のコントラストも確認してください。</p>
   <details><summary class="cursor-pointer font-semibold">モバイルの表示設定</summary><div class="mt-3 space-y-3"><label>文字サイズ（14〜48px・空欄ならPCと共通）<input type="number" min="14" max="48" bind:value={block.mobileSize}/></label><label>余白（0〜64px・空欄ならPCと共通）<input type="number" min="0" max="64" bind:value={block.mobilePadding}/></label><label class="flex items-center gap-2"><input type="checkbox" bind:checked={block.hideMobile}/>モバイルで非表示</label><label class="flex items-center gap-2"><input type="checkbox" bind:checked={block.hideDesktop}/>PCで非表示</label></div></details>
   <div class="flex flex-wrap gap-2"><button class="btn" onclick={()=>{checkpoint();doc.blocks.splice(doc.blocks.findIndex(b=>b.id===selected)+1,0,{...block!,id:crypto.randomUUID()});}}>複製</button><button class="btn" onclick={()=>{checkpoint();doc.blocks=doc.blocks.filter(b=>b.id!==selected);selected='';}}>削除</button><button class="btn" onclick={()=>void saveAsset('block')}>ブロック保存</button></div>
  </fieldset>{/if}</aside>
  <div class="workspace"><div class="mb-4 flex flex-wrap items-center justify-between gap-2"><div class="flex gap-2"><button class="btn" disabled={!history.length||disabled} onclick={undo}>元に戻す</button><button class="btn" disabled={!future.length||disabled} onclick={redo}>やり直す</button></div><div class="flex gap-2"><button class="btn" class:current={!mobile} onclick={()=>mobile=false}>PC</button><button class="btn" class:current={mobile} onclick={()=>mobile=true}>モバイル</button></div></div>
   <div class="canvas" style:max-width={mobile?'390px':'660px'}><iframe title="メールプレビュー" sandbox="" referrerpolicy="no-referrer" srcdoc={preview} class="preview"></iframe></div>
   <div class="mt-5 space-y-2"><h2 class="text-sm font-semibold">ブロックの順序・編集</h2>{#each doc.blocks as b,i (b.id)}<div class:selected={selected===b.id} class="block-row" draggable={!disabled} ondragstart={()=>dragId=b.id} ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,b.id)} role="group" aria-label={'ブロック '+(i+1)}><button class="flex-1 truncate text-left" onclick={()=>selected=b.id}>{i+1}. {blockLabels[b.kind]}　{b.text.replace(/<[^>]*>/g,'').slice(0,45)||b.alt}</button><button aria-label="上へ" disabled={disabled||i===0} onclick={()=>move(b.id,-1)}>↑</button><button aria-label="下へ" disabled={disabled||i===doc.blocks.length-1} onclick={()=>move(b.id,1)}>↓</button></div>{/each}</div>
  </div>
 </section>
{:else if tab==='checklist'}
 <div class="checklist"><section class="panel"><h2>件名・差出人</h2><label>件名<input bind:value={subject} disabled={disabled}/></label><label>プレヘッダー<input bind:value={preheader} disabled={disabled}/></label><label>差出人名<input bind:value={fromName} disabled={disabled}/></label><label>差出人メール<input type="email" bind:value={fromEmail} disabled={disabled}/></label><label>返信先<input type="email" bind:value={replyTo} disabled={disabled}/></label><p class="text-sm text-stone-500">差出人はResendで認証済みのドメインを指定してください。</p></section>
 <section class="panel"><h2>配信前チェック</h2>{#if issues.length}<ul class="space-y-2 text-sm text-amber-800">{#each issues as issue}<li>△ {issue}</li>{/each}</ul>{:else}<p class="text-sm text-emerald-700">✓ 空のブロック・リンク・代替テキストを確認しました。</p>{/if}<p class="text-sm text-stone-500">配信停止リンクと送信者情報は送信時に追加します。</p><button class="btn" disabled={dirty||disabled||!id} onclick={()=>void test()}>自分宛にテスト送信</button><p class="text-sm">最新テスト：{data.campaign?.tested_revision===revision?'送信済み':'未完了'}</p></section>
 <section class="panel"><h2>配信先</h2><p class="text-sm text-stone-500">未選択は配信可能な全コンタクト。複数選択は、いずれかのタグに該当する方が対象です。</p>{#each data.lists as list}<label class="flex items-center gap-2"><input type="checkbox" disabled={disabled} checked={list.tags.every((t:string)=>tags.includes(t))} onchange={e=>{tags=e.currentTarget.checked?[...new Set([...tags,...list.tags])]:tags.filter(t=>!list.tags.includes(t));count=null;}}/>{list.name}</label>{/each}<details><summary class="cursor-pointer text-sm font-semibold">条件付きリスト・詳細な絞り込み</summary><div class="mt-4 space-y-4">{#each data.lists.filter(l=>l.query&&l.query!=='{}') as list}<button class="btn" disabled={disabled} onclick={()=>{filter=savedAudience(list.query);tags=[...list.tags];}}>{list.name}の条件を使用</button>{/each}<MailAudience bind:value={filter} {disabled}/><button class="btn" disabled={disabled} onclick={()=>filter={}}>条件をクリア</button></div></details><button class="btn" onclick={()=>void audience()}>対象者数を確認</button>{#if count!==null}<p class="text-xl font-semibold">{count.toLocaleString()}件</p>{/if}</section>
 <section class="panel"><h2>配信日時</h2><label>日時を指定（空欄なら今すぐ）<input type="datetime-local" bind:value={schedule} disabled={disabled}/></label><p class="text-sm text-stone-500">端末のタイムゾーンで設定されます。</p>{#if data.campaign?.status==='scheduled'}<button class="btn" onclick={()=>void cancel()}>予約を取り消す</button>{:else}<button class="btn primary" disabled={disabled||dirty||!id||count===null||!count||data.campaign?.tested_revision!==revision} onclick={()=>confirming=true}>配信内容を確認</button>{/if}</section>
 </div>
{:else}<section class="panel"><h2>配信状況</h2><button class="btn" onclick={()=>void invalidateAll()}>更新</button><div class="grid grid-cols-2 gap-4 md:grid-cols-4">{#each [['送信',data.summary?.sent??'—'],['開封',data.summary?.opened??'—'],['クリック',data.summary?.clicked??'—'],['失敗・要確認',data.summary?.failed??'—']] as [label,n]}<div class="rounded-lg bg-stone-50 p-4"><p class="text-sm">{label}</p><p class="text-2xl font-semibold">{n}</p></div>{/each}</div>{#each data.deliveries.filter(d=>d.error) as d}<p class="text-sm text-red-700">{d.kind==='test'?'テスト':'本配信'}：{d.error}</p>{/each}</section>{/if}
{#if confirming}<MailDialog title="配信確認" onDismiss={()=>confirming=false}><section class="panel"><h2>この内容で配信します</h2><p class="font-semibold">{subject}</p><p>差出人：{fromName} &lt;{fromEmail}&gt;</p><p>対象：{count}件 ／ {schedule||'今すぐ'}</p><p class="text-sm">配信後は取り消せません。対象件数を入力して確定してください。</p><input aria-label="確認用の対象件数" bind:value={confirmCount} inputmode="numeric"/><div class="flex gap-2"><button class="btn" onclick={()=>confirming=false}>戻る</button><button class="btn primary" disabled={confirmCount!==String(count)} onclick={()=>void dispatch()}>配信を確定</button></div></section></MailDialog>{/if}
<style>
 .studio-header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}.btn{min-height:44px;border:1px solid #d6d3d1;border-radius:8px;padding:8px 14px;background:white;font-size:14px;cursor:pointer}.btn:hover{background:#f5f5f4}.btn:disabled{opacity:.45;cursor:default}.primary,.current{background:#292524;color:white;border-color:#292524}.primary:hover{background:#44403c}.studio{display:grid;grid-template-columns:300px minmax(0,1fr);border:1px solid #e7e5e4;border-radius:12px;overflow:hidden;background:white}.tools{padding:20px;border-right:1px solid #e7e5e4;max-height:calc(100vh - 180px);overflow:auto}.tile{min-height:76px;border:1px solid #e7e5e4;border-radius:10px;padding:12px;background:white;text-align:center;font-size:14px}.tile:hover{border-color:#a8a29e;background:#fafaf9}.workspace{padding:20px;background:#f5f5f4;min-width:0}.canvas{margin:auto;transition:max-width .2s}.preview{width:100%;height:650px;border:0;background:white;border-radius:6px}.block-row{display:flex;gap:16px;padding:12px;border:1px solid #d6d3d1;border-radius:8px;background:white;font-size:14px}.block-row.selected{border-color:#8b282e;box-shadow:0 0 0 1px #8b282e}.checklist{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{padding:24px;border:1px solid #e7e5e4;border-radius:12px;background:white;display:flex;flex-direction:column;gap:16px}.panel h2{font-size:18px;font-weight:600}label{display:block;font-size:14px}input:not([type=checkbox]):not([type=color]),textarea,select{display:block;width:100%;margin-top:6px;border:1px solid #d6d3d1;border-radius:7px;padding:10px;background:white;font-size:14px}input[type=color]{margin-top:6px;height:36px;width:100%}:global(button:focus-visible),:global(a:focus-visible){outline:2px solid #8b282e;outline-offset:3px}@media(max-width:900px){.studio{grid-template-columns:1fr}.tools{max-height:none;border-right:0;border-bottom:1px solid #e7e5e4}.workspace{padding:12px}.checklist{grid-template-columns:1fr}}
</style>
